/**
  * @brief  Register Bus IOs if component ID is OK
  * @param  Instance TS instance. Could be only 0.
  * @retval BSP status
  */
int32_t GT911_Probe(uint32_t Instance)
{
  int32_t ret             = BSP_ERROR_NONE;
  GT911_IO_t              IOCtx;
  static GT911_Object_t   GT911Obj;
  uint32_t gt911_id       = 0;
  uint32_t addressIndex = 0;
  const uint16_t addresses[2] = {TS_I2C_ADDRESS_GT, TS_I2C_ADDRESS_BACK};

  /* Configure the touch screen driver */
  IOCtx.Init        = BSP_I2C4_Init;
  IOCtx.DeInit      = BSP_I2C4_DeInit;
  IOCtx.ReadReg     = BSP_I2C4_ReadReg16;
  IOCtx.WriteReg    = BSP_I2C4_WriteReg16;
  IOCtx.GetTick     = BSP_GetTick;
  while (addressIndex < 2)
  {
    /* Configure the I2C slave address */
    IOCtx.Address     = addresses[addressIndex];
    if (GT911_RegisterBusIO(&GT911Obj, &IOCtx) != GT911_OK)
    {
      ret = BSP_ERROR_BUS_FAILURE;
    }
    else if (GT911_ReadID(&GT911Obj, &gt911_id) != GT911_OK)
    {
      ret = BSP_ERROR_COMPONENT_FAILURE;
    }
    else if (gt911_id != GT911_ID)
    {
      ret = BSP_ERROR_UNKNOWN_COMPONENT;
    }
    else
    {
      Ts_CompObj[Instance] = &GT911Obj;
      Ts_Drv = (TS_Drv_t *) &GT911_TS_Driver;

      if (Ts_Drv->Init(Ts_CompObj[Instance]) == GT911_OK)
      {
        return BSP_ERROR_NONE;
      }
      else
      {
        ret = BSP_ERROR_COMPONENT_FAILURE;
      }
    }
    /* Switch to the backup address if the first attempt failed */
    addressIndex++;
  }

  return ret;
}

/**
  * @brief  Register Bus IOs if component ID is OK
  * @param  Instance TS instance. Could be only 0.
  * @retval BSP status
  */
int32_t FT5336_Probe(uint32_t Instance)
{
  int32_t ret = BSP_ERROR_NONE;
  FT5336_IO_t              IOCtx;
  static FT5336_Object_t   FT5336Obj;
  uint32_t ft5336_id       = 0;

  /* Configure the touch screen driver */
  IOCtx.Address     = TS_I2C_ADDRESS;
  IOCtx.Init        = BSP_I2C4_Init;
  IOCtx.DeInit      = BSP_I2C4_DeInit;
  IOCtx.ReadReg     = BSP_I2C4_ReadReg;
  IOCtx.WriteReg    = BSP_I2C4_WriteReg;
  IOCtx.GetTick     = BSP_GetTick;

  if (FT5336_RegisterBusIO(&FT5336Obj, &IOCtx) != FT5336_OK)
  {
    ret = BSP_ERROR_BUS_FAILURE;
  }
  else if (FT5336_ReadID(&FT5336Obj, &ft5336_id) != FT5336_OK)
  {
    ret = BSP_ERROR_COMPONENT_FAILURE;
  }
  else if (ft5336_id != FT5336_ID)
  {
    ret = BSP_ERROR_UNKNOWN_COMPONENT;
  }
  else
  {
    Ts_CompObj[Instance] = &FT5336Obj;
    Ts_Drv = (TS_Drv_t *) &FT5336_TS_Driver;

    if (Ts_Drv->Init(Ts_CompObj[Instance]) != FT5336_OK)
    {
      ret = BSP_ERROR_COMPONENT_FAILURE;
    }
  }

  return ret;
}

